INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle PCI-Steckplätze gleich groß?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Längen wie x16, x8"}, {"text": "Ja", "correct": false, "because": "Größen variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptzweck dieser Erweiterungsslots?', 3, '[{"text": "Anschluss von Zusatzhardware", "correct": true, "because": "Ermöglicht Grafikkarten oder SSDs"}, {"text": "Speichererweiterung", "correct": false, "because": "RAM nutzt andere Slots"}, {"text": "Manuelle Kühlung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte werden typischerweise in diese Slots eingebaut?', 5, '[{"text": "Grafikkarten", "correct": true, "because": "Nutzen hohe Bandbreite"}, {"text": "Netzwerkkarten", "correct": true, "because": "Für zusätzliche Konnektivität"}, {"text": "Tastaturen", "correct": false, "because": "Nutzen USB"}, {"text": "Monitore", "correct": false, "because": "Andere Anschlüsse"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PCIe x16 bietet die höchste Bandbreite. b) Alle Slots sind abwärtskompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Versionen ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Steckplatzes?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Muss zu Karte passen"}, {"text": "Bandbreite", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Gehäusefarbe", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PCIe-Slots nur für Grafikkarten sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für SSDs oder Soundkarten"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal ist für die Leistung eines Slots entscheidend?', 3, '[{"text": "Anzahl der Lanes", "correct": true, "because": "Bestimmt Bandbreite"}, {"text": "Slotfarbe", "correct": false, "because": "Nur ästhetisch"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Automatisch erkannt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten moderne PCIe-Slots?', 5, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Ermöglicht schnelle Datenübertragung"}, {"text": "Abwärtskompatibilität", "correct": true, "because": "Unterstützt ältere Karten"}, {"text": "Eingebaute Kühlung", "correct": false, "because": "Nicht im Slot"}, {"text": "Softwaresteuerung", "correct": false, "because": "Hardwarebasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) PCIe 4.0 ist schneller als 3.0. b) Alle Slots unterstützen NVMe. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Mainboard ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht universell"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Nutzung eines PCIe-Slots?', 4, '[{"text": "Kompatible Hardware", "correct": false, "because": "Notwendig für Funktion"}, {"text": "Ausreichende Stromversorgung", "correct": false, "because": "Wichtig für Betrieb"}, {"text": "Externes Laufwerk", "correct": true, "because": "Nicht für PCIe nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind PCIe-Slots nur auf Desktops verfügbar?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Servern und Laptops"}, {"text": "Ja", "correct": false, "because": "Breiter Einsatzbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren bestimmen die Leistung eines Slots?', 4, '[{"text": "PCIe-Version", "correct": true, "because": "Höhere Versionen sind schneller"}, {"text": "Lane-Anzahl", "correct": true, "because": "Mehr Lanes erhöhen Bandbreite"}, {"text": "Gehäusegröße", "correct": false, "because": "Kein Leistungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass PCIe-Slots immer Strom liefern. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Bis zu 75W über Slot"}, {"text": "Nein", "correct": false, "because": "Stromversorgung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl eines Slots für eine Grafikkarte?', 3, '[{"text": "x16-Slot", "correct": true, "because": "Maximale Bandbreite"}, {"text": "Kleine Größe", "correct": false, "because": "x16 für GPUs nötig"}, {"text": "Manuelle Einstellung", "correct": false, "because": "Automatisch erkannt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PCIe-Slots unterstützen Hot-Plugging. b) Sie sind nur für Grafikkarten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist vielseitiger"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei PCIe-Slots?', 5, '[{"text": "Kompatibilitätsprobleme", "correct": true, "because": "Versionen müssen übereinstimmen"}, {"text": "Platzbeschränkungen", "correct": true, "because": "Begrenzen Installation"}, {"text": "Hohe Latenz", "correct": false, "because": "Nicht typisch"}, {"text": "Softwareabhängigkeit", "correct": false, "because": "Hardwarebasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung eines Slots unwichtig?', 3, '[{"text": "PCIe-Version", "correct": false, "because": "Bestimmt Geschwindigkeit"}, {"text": "Strombedarf", "correct": false, "because": "Sichert Betrieb"}, {"text": "Schriftart", "correct": true, "because": "Kein Hardwarefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PCIe-Slots für NVMe-SSDs geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Unterstützen hohe Geschwindigkeiten"}, {"text": "Nein", "correct": false, "because": "NVMe nutzt PCIe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordern PCIe-Slots immer eine x16-Karte?', 3, '[{"text": "Nein", "correct": true, "because": "Auch x1 oder x4 möglich"}, {"text": "Ja", "correct": false, "because": "Verschiedene Größen nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Nutzung eines PCIe-Slots?', 4, '[{"text": "Installation einer High-End-GPU", "correct": true, "because": "Benötigt x16-Bandbreite"}, {"text": "Anschluss eines Druckers", "correct": false, "because": "Nutzt USB"}, {"text": "Speichererweiterung", "correct": false, "because": "RAM-Slots genutzt"}]');
